import React, { useState,useEffect } from 'react'
import vivid from '../Images/vivid.jpg'
import ecom from '../Images/uzhavan.png'
import mamcet from '../Images/mamcet.png' 
import teckon from '../Images/symposiyum.png' 
import pro from '../Images/webbee.png'
import { BsGithub } from "react-icons/bs";
import Element from 'react-scroll/modules/components/Element'
import './project.css'

const slides = [
    {
        image: vivid,
        description: 'Online Book Store',
        link: 'https://github.com/pravinsathishprabu/Online-Book-Store',
    },
    {
        image: ecom,
        description: 'Food Product E-commerce and Crop Disease Prediction Platform',
        link: 'https://github.com/pravinsathishprabu/E-commerce-for-food-products-and-Crop-disease-prediction',
    },
    {
        image: pro,
        description: 'Online Social Media',
        link: 'https://github.com/pravinsathishprabu/Online-Social-Media',
    },
    {
        image: mamcet,
        description: 'Attendance Management System in Laravel',
        link: 'https://github.com/pravinsathishprabu/Attendance-Management-System',
    },
    {
        image: teckon,
        description: 'Teckon 2023 - National Level Technical Symposiyum',
        link: 'https://teckon2023.000webhostapp.com/',
    },
];

const Project = () => {

    const [currentIndex, setCurrentIndex] = useState(0);

    const nextSlide = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === slides.length - 1 ? 0 : prevIndex + 1
        );
    };
// Auto slide effect
    useEffect(() => {
        const intervalId = setInterval(nextSlide, 5000); // Change slide every 5 seconds

        return () => clearInterval(intervalId); // Cleanup on unmount
    }, []);

    const prevSlide = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === 0 ? slides.length - 1 : prevIndex - 1
        );
    };


  return (
    <Element className='projectcontainer mt-4' id='project'>
            <br/>
            <center><strong className='mt-4 highlights'>Projects</strong></center>
            <hr/>
             <div className="slider mt-4">
            <button onClick={prevSlide} className="arrow left-arrow">
                <span> &#10094; </span>
            </button>
            <div className="slide-content">
                <img src={slides[currentIndex].image} alt={`Slide ${currentIndex + 1}`} />
                <p className='text-primary p-2'>{slides[currentIndex].description}</p>
                <a href={slides[currentIndex].link} className="btn btn-dark">
                   <BsGithub/>&nbsp; View
                </a>
            </div>
            <button onClick={nextSlide} className="arrow right-arrow">
                <span> &#10095; </span>
            </button>
        </div>
     </Element>
  )
}

export default Project
